public class SpecialSpellingProbe {public static void main(String[] args){System.out.println("0.0f / 0.0f="+Integer.toHexString(Float.floatToRawIntBits(0.0f / 0.0f)));System.out.println("-(0.0f / 0.0f)="+Integer.toHexString(Float.floatToRawIntBits(-(0.0f / 0.0f))));System.out.println("1.0f / 0.0f="+Integer.toHexString(Float.floatToRawIntBits(1.0f / 0.0f)));System.out.println("-1.0f / 0.0f="+Integer.toHexString(Float.floatToRawIntBits(-1.0f / 0.0f)));System.out.println("0.0d / 0.0d="+Long.toHexString(Double.doubleToRawLongBits(0.0d / 0.0d)));System.out.println("-(0.0d / 0.0d)="+Long.toHexString(Double.doubleToRawLongBits(-(0.0d / 0.0d))));System.out.println("1.0d / 0.0d="+Long.toHexString(Double.doubleToRawLongBits(1.0d / 0.0d)));System.out.println("-1.0d / 0.0d="+Long.toHexString(Double.doubleToRawLongBits(-1.0d / 0.0d)));}}
